begin;
set local search_path=extensions,public,private;
select no_plan();
insert into auth.sessions(id,user_id) select md5('pgtap-session:'||id::text)::uuid,id from auth.users on conflict do nothing;
update private.meetup_feature_config set enabled=true,expanded_launch_gates_passed=true where id=1;
update private.commerce_configuration set mode='sandbox';
insert into private.member_subscriptions(account_id,tier,paid_until,source)
select id,'plebba_kongur',now()+interval '1 month','sandbox' from public.profiles
on conflict(account_id) do update set tier=excluded.tier,paid_until=excluded.paid_until;
create function pg_temp.memory_member(p_id uuid) returns void language plpgsql as $$begin
 perform set_config('request.jwt.claim.sub',coalesce(p_id::text,''),true);
 perform set_config('request.jwt.claim.role',case when p_id is null then 'anon' else 'authenticated' end,true);
 perform set_config('request.jwt.claims',case when p_id is null then '{}' else jsonb_build_object('sub',p_id,'session_id',md5('pgtap-session:'||p_id::text)::uuid,'role','authenticated')::text end,true);
end $$;
create function pg_temp.memory_event(p_n integer) returns uuid language sql immutable as $$select ('96500000-0000-0000-0000-'||lpad(p_n::text,12,'0'))::uuid$$;
create function pg_temp.memory_settings(p_enabled boolean) returns jsonb language sql immutable as $$select jsonb_build_object('enabled',p_enabled,'title','Our gathering','description','A public showcase','layout','grid','accentColor','#25836A')$$;
insert into public.meetups(id,host_id,title,description,category,starts_at,access_mode,location_visibility,general_area,capacity,prohibited_services_attested_at,status,published_at)
select pg_temp.memory_event(n),'10000000-0000-0000-0000-000000000001','Memory wall test gathering','Synthetic memory wall gathering','community',now()-interval '1 hour','open','protected','reykjavik',8,now(),'published',now() from generate_series(1,3) n;
update public.meetups set access_mode='private' where id=pg_temp.memory_event(2);
update public.meetups set starts_at=now()+interval '1 day' where id=pg_temp.memory_event(3);
insert into private.community_attendance(meetup_id,profile_id,source) values(pg_temp.memory_event(1),'10000000-0000-0000-0000-000000000002','moderator');
select ok(not has_table_privilege('anon','private.meetup_memories','select'),'raw memory rows are private');
select ok(not has_table_privilege('authenticated','private.meetup_memory_likes','select'),'liker identities are private');
select ok(not has_table_privilege('authenticated','private.meetup_memory_comments','insert'),'comments require the authorized RPC');
select ok(not has_function_privilege('anon','public.reserve_meetup_memory(uuid,text,text)','execute'),'anonymous visitors cannot reserve uploads');
select ok(not has_function_privilege('authenticated','private.memory_post_payload(uuid,uuid)','execute'),'clients cannot invoke unchecked internal payload builders');
select ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like '%meetup_memory%' and p.prosecdef),'new public memory endpoints use invoker wrappers');
select is((select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='private' and c.relname in ('meetup_memory_walls','meetup_memories','meetup_memory_likes','meetup_memory_comments') and c.relrowsecurity),4::bigint,'all new private tables also enable RLS');
set local role anon;
select pg_temp.memory_member(null);
select throws_ok($$select public.get_meetup_memory_wall(pg_temp.memory_event(1))$$,'42501','memory_wall_unavailable','wall is private until a host enables it');
select throws_ok($$select * from private.meetup_memories$$,'42501',null::text,'anonymous raw-table access is denied');
set local role authenticated;
select pg_temp.memory_member('10000000-0000-0000-0000-000000000003');
select throws_ok($$select public.update_meetup_memory_wall(pg_temp.memory_event(1),pg_temp.memory_settings(true))$$,'42501','meetup_host_required','a member cannot enable another host wall');
select pg_temp.memory_member('10000000-0000-0000-0000-000000000001');
select lives_ok($$select public.get_meetup_memory_wall(pg_temp.memory_event(1))$$,'host can inspect disabled settings');
select lives_ok($$select public.update_meetup_memory_wall(pg_temp.memory_event(1),pg_temp.memory_settings(true))$$,'host configures a public wall');
select throws_ok($$select public.update_meetup_memory_wall(pg_temp.memory_event(2),pg_temp.memory_settings(true))$$,'42501','memory_wall_public_meetup_required','private gatherings cannot publish public walls');
select throws_ok($$select public.update_meetup_memory_wall(pg_temp.memory_event(1),pg_temp.memory_settings(true)||'{"extra":"value"}'::jsonb)$$,'22023','invalid_memory_wall_settings','settings reject unknown keys');
select throws_ok($$select public.update_meetup_memory_wall(pg_temp.memory_event(1),jsonb_set(pg_temp.memory_settings(true),'{accentColor}','"javascript:bad"'))$$,'22023','invalid_memory_wall_settings','accent color is validated');
select lives_ok($$select public.update_meetup_memory_wall(pg_temp.memory_event(3),pg_temp.memory_settings(true))$$,'future public gatherings can configure their wall');
select throws_ok($$select public.reserve_meetup_memory(pg_temp.memory_event(3),'photo','')$$,'42501','verified_attendee_required','memories cannot be uploaded before the gathering starts');
select pg_temp.memory_member('10000000-0000-0000-0000-000000000003');
select throws_ok($$select public.reserve_meetup_memory(pg_temp.memory_event(1),'photo','')$$,'42501','verified_attendee_required','ordinary viewers cannot upload without recorded attendance');
select pg_temp.memory_member('10000000-0000-0000-0000-000000000002');
select set_config('test.memory_photo',public.reserve_meetup_memory(pg_temp.memory_event(1),'photo','An afternoon together')::text,true);
select is(public.get_meetup_memory_wall(pg_temp.memory_event(1))->>'canPost','true','recorded attendee can share memories');
select is(jsonb_array_length(public.get_meetup_memory_wall(pg_temp.memory_event(1))->'posts'),0,'reserved originals are invisible');
reset role;
select set_config('test.memory_claim',gen_random_uuid()::text,true);
update private.media_uploads set status='processing',claim_id=current_setting('test.memory_claim')::uuid,expires_at=now()+interval '15 minutes' where id=(current_setting('test.memory_photo')::jsonb->>'id')::uuid;
set local role service_role;
select set_config('request.jwt.claim.role','service_role',true);
select ok(public.finish_media_upload((current_setting('test.memory_photo')::jsonb->>'id')::uuid,current_setting('test.memory_claim')::uuid,100,null,pg_temp.memory_event(1)::text||'/'||(current_setting('test.memory_photo')::jsonb->>'id')||'.jpg',null,null),'reviewed attendee photo publishes through the existing worker');
reset role;
insert into storage.objects(bucket_id,name) values('meetup-media',pg_temp.memory_event(1)::text||'/'||(current_setting('test.memory_photo')::jsonb->>'id')||'.jpg'),('meetup-media',pg_temp.memory_event(1)::text||'/host-gallery.jpg'),('media-quarantine',current_setting('test.memory_photo')::jsonb->>'path');
set local role anon;
select pg_temp.memory_member(null);
select is(jsonb_array_length(public.get_meetup_memory_wall(pg_temp.memory_event(1))->'posts'),1,'anonymous visitors can see approved memories');
select is(public.get_meetup_memory_wall(pg_temp.memory_event(1))#>'{posts,0,authorId}','null'::jsonb,'public projection omits profile identifiers');
select alike(public.get_meetup_memory_wall(pg_temp.memory_event(1))#>>'{posts,0,authorName}','Member %','public projection uses an occurrence-specific member name');
select ok(not public.get_meetup_memory_wall(pg_temp.memory_event(1)) ?| array['location','attendees','attendance','hostId','diagnoses'],'public wall omits location and attendance metadata');
select is((select count(*) from storage.objects where bucket_id='meetup-media' and name=pg_temp.memory_event(1)::text||'/'||(current_setting('test.memory_photo')::jsonb->>'id')||'.jpg'),1::bigint,'approved memory storage is readable anonymously');
select is((select count(*) from storage.objects where name=pg_temp.memory_event(1)::text||'/host-gallery.jpg'),0::bigint,'public memory policy does not expose host gallery paths');
select is((select count(*) from storage.objects where bucket_id='media-quarantine'),0::bigint,'original quarantine objects stay private');
select throws_ok($$select public.get_meetup_memory_wall(pg_temp.memory_event(1),51,0)$$,'22023','invalid_memory_page','page size is bounded');
select throws_ok($$select public.get_meetup_memory_wall(pg_temp.memory_event(1),30,10001)$$,'22023','invalid_memory_page','offset is bounded');
set local role authenticated;
select pg_temp.memory_member('10000000-0000-0000-0000-000000000003');
select lives_ok($$select public.set_meetup_memory_like((current_setting('test.memory_photo')::jsonb->>'id')::uuid,true)$$,'active member can like an approved memory');
select lives_ok($$select public.set_meetup_memory_like((current_setting('test.memory_photo')::jsonb->>'id')::uuid,true)$$,'likes are idempotent');
select is(public.get_meetup_memory_wall(pg_temp.memory_event(1))#>>'{posts,0,likeCount}','1','duplicate likes count once');
select set_config('test.memory_comment',public.add_meetup_memory_comment((current_setting('test.memory_photo')::jsonb->>'id')::uuid,'Good memories')::text,true);
select is(public.get_meetup_memory_wall(pg_temp.memory_event(1))#>>'{posts,0,commentCount}','1','comments appear on the public wall');
select throws_ok($$select public.add_meetup_memory_comment((current_setting('test.memory_photo')::jsonb->>'id')::uuid,'   ')$$,'22023','invalid_memory_comment','empty comments are rejected');
select throws_ok($$select public.pin_meetup_memory((current_setting('test.memory_photo')::jsonb->>'id')::uuid,true)$$,'42501','meetup_host_required','only the host can pin a memory');
select throws_ok($$select public.delete_meetup_memory((current_setting('test.memory_photo')::jsonb->>'id')::uuid)$$,'42501','memory_unavailable','viewers cannot delete attendee memories');
select pg_temp.memory_member('10000000-0000-0000-0000-000000000002');
select throws_ok($$select public.delete_meetup_memory_comment((current_setting('test.memory_comment')::jsonb->>'id')::uuid)$$,'42501','memory_comment_unavailable','post author cannot remove someone else comment');
select pg_temp.memory_member('10000000-0000-0000-0000-000000000001');
select lives_ok($$select public.pin_meetup_memory((current_setting('test.memory_photo')::jsonb->>'id')::uuid,true)$$,'host can pin attendee memories');
select lives_ok($$select public.delete_meetup_memory_comment((current_setting('test.memory_comment')::jsonb->>'id')::uuid)$$,'host can moderate comments');
reset role;
insert into public.blocks(blocker_id,blocked_id) values('10000000-0000-0000-0000-000000000003','10000000-0000-0000-0000-000000000002');
set local role authenticated;
select pg_temp.memory_member('10000000-0000-0000-0000-000000000003');
select is(jsonb_array_length(public.get_meetup_memory_wall(pg_temp.memory_event(1))->'posts'),0,'blocked authors are hidden from a signed-in viewer');
select throws_ok($$select public.set_meetup_memory_like((current_setting('test.memory_photo')::jsonb->>'id')::uuid,true)$$,'42501','memory_unavailable','blocked members cannot interact with that author');
reset role;
delete from public.blocks where blocker_id='10000000-0000-0000-0000-000000000003' and blocked_id='10000000-0000-0000-0000-000000000002';
update public.profiles set moderation_status='suspended', suspended_until=now()+interval '1 day' where id='10000000-0000-0000-0000-000000000002';
set local role anon;
select pg_temp.memory_member(null);
select is(jsonb_array_length(public.get_meetup_memory_wall(pg_temp.memory_event(1))->'posts'),0,'moderation removes author memories from public projection');
reset role;
update public.profiles set moderation_status='active', suspended_until=null where id='10000000-0000-0000-0000-000000000002';
set local role authenticated;
select pg_temp.memory_member('10000000-0000-0000-0000-000000000001');
select lives_ok($$select public.update_meetup_memory_wall(pg_temp.memory_event(1),pg_temp.memory_settings(false))$$,'host can hide the wall');
select is(jsonb_array_length(public.get_meetup_memory_wall(pg_temp.memory_event(1))->'posts'),0,'host disabled-wall settings omit media');
set local role anon;
select pg_temp.memory_member(null);
select throws_ok($$select public.get_meetup_memory_wall(pg_temp.memory_event(1))$$,'42501','memory_wall_unavailable','disabled wall revokes anonymous access');
select is((select count(*) from storage.objects where bucket_id='meetup-media'),0::bigint,'disabling a wall revokes new storage reads');
set local role authenticated;
select pg_temp.memory_member('10000000-0000-0000-0000-000000000001');
select public.update_meetup_memory_wall(pg_temp.memory_event(1),pg_temp.memory_settings(true));
select pg_temp.memory_member('10000000-0000-0000-0000-000000000002');
select ok(public.export_account() ? 'meetupMemories','account export includes user memory contributions');
select lives_ok($$select public.delete_meetup_memory((current_setting('test.memory_photo')::jsonb->>'id')::uuid)$$,'author can delete their own public memory');
reset role;
select is((select count(*) from private.meetup_memory_likes where post_id=(current_setting('test.memory_photo')::jsonb->>'id')::uuid),0::bigint,'memory deletion cascades likes');
select is((select status from private.media_uploads where id=(current_setting('test.memory_photo')::jsonb->>'id')::uuid),'rejected','deletion makes the original upload ineligible');
select ok(exists(select 1 from private.media_cleanup_jobs where bucket='meetup-media' and name=pg_temp.memory_event(1)::text||'/'||(current_setting('test.memory_photo')::jsonb->>'id')||'.jpg'),'memory deletion durably queues normalized media cleanup');
-- A processing upload can still be writing output after its occurrence is
-- removed. Durable cleanup must retain its prior lease before draining files.
set local role authenticated;
select pg_temp.memory_member('10000000-0000-0000-0000-000000000002');
select set_config('test.memory_video',public.reserve_meetup_memory(pg_temp.memory_event(1),'video','Our evening')::text,true);
reset role;
update private.media_uploads set status='processing',claim_id=current_setting('test.memory_claim')::uuid,expires_at=now()+interval '15 minutes' where id=(current_setting('test.memory_video')::jsonb->>'id')::uuid;
set local role service_role;
select set_config('request.jwt.claim.role','service_role',true);
select throws_ok($$select public.finish_media_upload((current_setting('test.memory_video')::jsonb->>'id')::uuid,current_setting('test.memory_claim')::uuid,100,1000,pg_temp.memory_event(1)::text||'/'||(current_setting('test.memory_video')::jsonb->>'id')||'.mp4',null,null)$$,'P0001','invalid_verified_media','video publication requires an inspected poster');
select ok(public.finish_media_upload((current_setting('test.memory_video')::jsonb->>'id')::uuid,current_setting('test.memory_claim')::uuid,100,1000,pg_temp.memory_event(1)::text||'/'||(current_setting('test.memory_video')::jsonb->>'id')||'.mp4',pg_temp.memory_event(1)::text||'/'||(current_setting('test.memory_video')::jsonb->>'id')||'-thumb.jpg',null),'reviewed video and poster publish together');
set local role authenticated;
select pg_temp.memory_member('10000000-0000-0000-0000-000000000002');
select set_config('test.memory_cancelled',public.reserve_meetup_memory(pg_temp.memory_event(1),'video','')::text,true);
reset role;
update private.media_uploads set status='processing',claim_id=current_setting('test.memory_claim')::uuid,expires_at=now()+interval '15 minutes' where id=(current_setting('test.memory_cancelled')::jsonb->>'id')::uuid;
update private.media_uploads set status='rejected',rejection_reason='upload_cancelled',claim_id=null where id=(current_setting('test.memory_cancelled')::jsonb->>'id')::uuid;
select is((select count(*) from private.media_cleanup_jobs where name in (
 pg_temp.memory_event(1)::text||'/'||(current_setting('test.memory_cancelled')::jsonb->>'id')||'.mp4',
 pg_temp.memory_event(1)::text||'/'||(current_setting('test.memory_cancelled')::jsonb->>'id')||'-thumb.jpg',
 current_setting('test.memory_cancelled')::jsonb->>'path') and available_at>=now()+interval '15 minutes'),3::bigint,'processing cancellation defers original, video and poster cleanup until the old lease ends');
set local role authenticated;
select pg_temp.memory_member('10000000-0000-0000-0000-000000000002');
select set_config('test.memory_deleted_event',public.reserve_meetup_memory(pg_temp.memory_event(1),'photo','')::text,true);
reset role;
update private.media_uploads set status='processing',claim_id=current_setting('test.memory_claim')::uuid,expires_at=now()+interval '15 minutes' where id=(current_setting('test.memory_deleted_event')::jsonb->>'id')::uuid;
delete from public.meetups where id=pg_temp.memory_event(1);
select is((select count(*) from private.meetup_memories where meetup_id=pg_temp.memory_event(1)),0::bigint,'occurrence deletion cascades its published memories');
select ok(exists(select 1 from private.media_cleanup_jobs where bucket='meetup-media' and name=pg_temp.memory_event(1)::text||'/'||(current_setting('test.memory_video')::jsonb->>'id')||'-thumb.jpg'),'occurrence deletion queues the published video poster');
select is((select status from private.media_uploads where id=(current_setting('test.memory_deleted_event')::jsonb->>'id')::uuid),'rejected','occurrence deletion cancels processing memory jobs');
select ok(exists(select 1 from private.media_cleanup_jobs where bucket='meetup-media' and name=pg_temp.memory_event(1)::text||'/'||(current_setting('test.memory_deleted_event')::jsonb->>'id')||'.jpg' and available_at>=now()+interval '15 minutes'),'occurrence deletion preserves a processing job lease for cleanup');
select * from finish();
rollback;
